func:
if (flow.get('is_processing') === true) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Locked (already processing)' });
    return null;
}

flow.set('is_processing', true);
node.status({ fill: 'blue', shape: 'dot', text: 'Lock acquired' });
return msg;

var content = msg.payload || '';
var lines = content.split('\n');
var adapter = 'live_opencode';
var nodeRedUrl = 'http://localhost:1880';

for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line === '' || line.indexOf('#') === 0) continue;
    var parts = line.split(':');
    if (parts.length >= 2) {
        var key = parts[0].trim();
        var val = parts.slice(1).join(':').trim();
        // Strip quotes
        if ((val.indexOf('"') === 0 && val.lastIndexOf('"') === val.length - 1) ||
            (val.indexOf("'") === 0 && val.lastIndexOf("'") === val.length - 1)) {
            val = val.substring(1, val.length - 1);
        }
        if (key === 'agent_adapter') {
            var adapterParts = val.split(':');
            adapter = adapterParts.length > 1 ? adapterParts[1].trim() : val;
        } else if (key === 'node_red_url') {
            nodeRedUrl = val;
        }
    }
}

msg.adapter = adapter;
msg.nodeRedUrl = nodeRedUrl;
node.status({ fill: 'green', shape: 'dot', text: 'Adapter: ' + adapter });
return msg;

var stdout = (msg.payload || '').trim();
if (stdout !== '') {
    try {
        var failedTasks = JSON.parse(stdout);
        if (failedTasks && failedTasks.length > 0) {
            node.warn('Router blocked by failed task: ' + failedTasks[0].id + '. Waiting for Owner intervention...');
            node.status({ fill: 'red', shape: 'dot', text: 'Blocked by failed task: ' + failedTasks[0].id });
            flow.set('is_processing', false);
            return null;
        }
    } catch (e) {
        node.error('Error parsing failed tasks: ' + e.message);
    }
}
node.status({ fill: 'green', shape: 'ring', text: 'No blocked tasks' });
return msg;

var stdout = (msg.payload || '').trim();
if (stdout !== '') {
    try {
        var stuckTasks = JSON.parse(stdout);
        if (stuckTasks && stuckTasks.length > 0) {
            var task = stuckTasks[0];
            node.status({ fill: 'cyan', shape: 'dot', text: 'Lead Escalation for task ' + task.id });
            msg.task = task;
            msg.assigneeID = 5;
            return [null, msg];
        }
    } catch (e) {
        node.error('Error parsing stuck tasks: ' + e.message);
    }
}
return [msg, null];

var stdout = (msg.payload || '').trim();
if (stdout === '') {
    node.status({ fill: 'green', shape: 'ring', text: 'All tasks finished' });
    flow.set('is_processing', false);
    return null;
}
try {
    var tasks = JSON.parse(stdout);
    if (!tasks || tasks.length === 0) {
        node.status({ fill: 'green', shape: 'ring', text: 'All tasks finished' });
        flow.set('is_processing', false);
        return null;
    }
    var task = tasks[0];
    msg.task = task;
    msg.assigneeID = task.agent_id ? parseInt(task.agent_id) : 2;
    node.status({ fill: 'blue', shape: 'dot', text: 'Task ID: ' + task.id + ' (Assignee: ' + msg.assigneeID + ')' });
    return msg;
} catch (e) {
    node.error('Error parsing todo task: ' + e.message);
    flow.set('is_processing', false);
    return null;
}

if (!msg.task.agent_id) {
    msg.needs_db_assignment = true;
    msg.assigneeID = 2;
}
return msg;

var stdout = (msg.payload || '').trim();
var comments = [];
if (stdout !== '') {
    try {
        comments = JSON.parse(stdout);
    } catch (e) {
        node.error('Error parsing comments JSON: ' + e.message);
    }
}
msg.comments = comments;
return msg;

var role = 'dev';
if (msg.assigneeID === 3) role = 'tester';
else if (msg.assigneeID === 4) role = 'boss';
else if (msg.assigneeID === 5) role = 'lead';

msg.template_path = 'cmd/build/templates/' + role + '.md';
msg.payload = 'cat ' + msg.template_path;
return msg;

var template = msg.payload || '';
var task = msg.task;
var comments = msg.comments || [];

var commentsHistory = '';
if (comments.length > 0) {
    for (var i = 0; i < comments.length; i++) {
        commentsHistory += comments[i].role + ': ' + comments[i].content + '\n----------------------------------------\n';
    }
} else {
    commentsHistory = '(No comments yet)';
}

var contextContent = '\n\n---\n### YOUR CURRENT ASSIGNMENT\nTask ID: ' + task.id + '\nTitle: ' + task.title + '\nDescription: ' + (task.description || '') + '\n\n### COMMENTS HISTORY\n' + commentsHistory + '\n';

msg.agentPrompt = template + contextContent;

// Write to file inside Node-RED using inline node function (since fs is available, or write command)
// To be extremely robust, we will write the instructions file via standard echo/printf or node-red write
// We'll construct a shell command that writes the prompt safely, or writes it using sqlite or standard CLI
// Let's create a temporary file name:
var filepath = '.build/agent_' + msg.assigneeID + '.md';
msg.agentFile = filepath;

// We will write this prompt using fs inside Node-RED if we can, or construct an exec command
// Let's write the command to write the file, then execute the agent, then clean up!
// We will use standard cat and EOF to write to file safely in msg.payload
msg.payload = 'cat << \'EOF\' > ' + filepath + '\n' + msg.agentPrompt + '\nEOF\n' + 'agent ' + msg.adapter + ' < ' + filepath + '; rm -f ' + filepath;

return msg;

var stdout = (msg.payload || '').trim();
if (stdout !== '') {
    var roleName = 'Unknown';
    if (msg.assigneeID === 2) roleName = 'Dev';
    else if (msg.assigneeID === 3) roleName = 'Tester';
    else if (msg.assigneeID === 4) roleName = 'Boss';
    else if (msg.assigneeID === 5) roleName = 'Lead';

    var commitMsg = 'build: updates for task ' + msg.task.id + ' by ' + roleName;
    msg.payload = 'git commit -m "' + commitMsg + '"';
    msg.has_changes = true;
} else {
    msg.has_changes = false;
}
return msg;

var instructionMsg = '**CRITICAL**: Please review task ' + msg.task.id + ' and provide your feedback using the `build review` command.\n\n' +
    'The syntax is:\n' +
    'build review ' + msg.task.id + ' <approve|reject> "<reasoning>"\n\n' +
    'RULES:\n' +
    '1. Your reasoning MUST be a single line of text.\n' +
    '2. Enclose your reasoning in double quotes (").\n' +
    '3. DO NOT use double quotes inside your reasoning string (use single quotes instead).\n' +
    '4. DO NOT ask questions; provide ONLY the final review via the bash tool.';

msg.payload = "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 1, '" + instructionMsg.replace(/'/g, "''") + "'); UPDATE tasks SET agent_id = 4 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_boss', '" + msg.adapter + "', '', 'build');\"";
return msg;

var errorMsg = 'Tests failed:\n' + msg.payload;
// Fetch current approval attempts via subquery or just perform update with attempts incremented
msg.payload = "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 3, '" + errorMsg.replace(/'/g, "''") + "'); UPDATE tasks SET approval_attempts = approval_attempts + 1 WHERE id = '" + msg.task.id + "';\" && " +
    "sqlite3 -json .build/build.db \"SELECT approval_attempts, lead_interventions FROM tasks WHERE id = '" + msg.task.id + "'\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var attempts = res[0].approval_attempts;
    var lead_interventions = res[0].lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'stuck', agent_id = 5, approval_attempts = 0, lead_interventions = lead_interventions + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'escalate_to_lead', '" + msg.adapter + "', '', 'build');\"";
        } else {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'failed', agent_id = 1, approval_attempts = '" + attempts + "' WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\"";
        }
    } else {
        msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
    }
} catch (e) {
    node.error('Error parsing attempts JSON: ' + e.message);
    // Fallback to dev
    msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "';\"";
}
return msg;

var stdout = (msg.payload || '').trim();
if (stdout === '') {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: You exited without leaving a review. You MUST use build review to leave your evaluation.';
    return msg;
}

try {
    var comments = JSON.parse(stdout);
    if (!comments || comments.length === 0) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: No comments found. You MUST leave your evaluation.';
        return msg;
    }

    var lastComment = comments[0].content || '';
    var cleaned = lastComment.replace(/```json/g, '').replace(/```/g, '').trim();
    var payload = JSON.parse(cleaned);

    if (typeof payload.approval !== 'boolean' || !payload.reasoning) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: Missing approval (boolean) or reasoning (string) in your payload.';
        return msg;
    }

    msg.boss_approval = payload.approval;
    msg.boss_reasoning = payload.reasoning;
    msg.boss_eval_status = payload.approval ? 'approved' : 'rejected';
} catch (e) {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: Your review was not correctly formatted JSON. Please use build review.';
}
return msg;

msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET approval_attempts = approval_attempts + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\" && " +
    "sqlite3 -json .build/build.db \"SELECT approval_attempts, lead_interventions FROM tasks WHERE id = '" + msg.task.id + "'\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var attempts = res[0].approval_attempts;
    var lead_interventions = res[0].lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'stuck', agent_id = 5, approval_attempts = 0, lead_interventions = lead_interventions + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'escalate_to_lead', '" + msg.adapter + "', '', 'build');\"";
        } else {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'failed', agent_id = 1, approval_attempts = '" + attempts + "' WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\"";
        }
    } else {
        msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
    }
} catch (e) {
    node.error('Error parsing boss attempts: ' + e.message);
    msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "';\"";
}
return msg;

var formatErrMsg = msg.error_reason || 'System Error: Format validation failed.';
msg.payload = "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 1, '" + formatErrMsg.replace(/'/g, "''") + "'); UPDATE tasks SET approval_attempts = approval_attempts + 1 WHERE id = '" + msg.task.id + "';\" && " +
    "sqlite3 -json .build/build.db \"SELECT approval_attempts, lead_interventions FROM tasks WHERE id = '" + msg.task.id + "'\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var attempts = res[0].approval_attempts;
    var lead_interventions = res[0].lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'stuck', agent_id = 5, approval_attempts = 0, lead_interventions = lead_interventions + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'escalate_to_lead', '" + msg.adapter + "', '', 'build');\"";
        } else {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'failed', agent_id = 1, approval_attempts = '" + attempts + "' WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\"";
        }
    } else {
        msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 4 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_boss', '" + msg.adapter + "', '', 'build');\"";
    }
} catch (e) {
    node.error('Error parsing format err boss attempts: ' + e.message);
    msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 4 WHERE id = '" + msg.task.id + "';\"";
}
return msg;

var stdout = (msg.payload || '').trim();
var count = 0;
try {
    var res = JSON.parse(stdout);
    count = res[0].count;
} catch (e) {
    node.error('Error parsing lead comment check: ' + e.message);
}

var sql = '';
if (count === 0) {
    var note = 'System Note: The Lead Engineer reviewed the task but failed to leave explicit instructions. Developer, please carefully review the previous failures and try again.';
    sql += "sqlite3 .build/build.db \"INSERT INTO comments (task_id, agent_id, content) VALUES ('" + msg.task.id + "', 1, '" + note + "'); UPDATE tasks SET status = 'todo', agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
} else {
    sql += "sqlite3 .build/build.db \"UPDATE tasks SET status = 'todo', agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
}
msg.payload = sql;
return msg;

flow.set('is_processing', false);
node.status({ fill: 'green', shape: 'ring', text: 'Lock released / Idle' });
return msg;
